package main

import "core:fmt"

MAX_NUMBERS :: 4096

numbers: [MAX_NUMBERS]int
num_numbers: int

add_number :: proc(n: int) {
	if num_numbers == len(numbers) {
		fmt.eprintln("Out of numbers")
		return
	}

	numbers[num_numbers] = n
	num_numbers += 1
}

main :: proc() {
	add_number(7)
	add_number(42)

	fmt.println(numbers[:num_numbers])
}

